import { Redacted } from "effect";

/** Port the relay listens on when it runs on a developer machine. */
export const LOCAL_REGISTRY_RELAY_PORT = 4310;

/** Base URL of the relay when it runs on a developer machine. */
export const LOCAL_REGISTRY_RELAY_URL = `http://127.0.0.1:${LOCAL_REGISTRY_RELAY_PORT}`;

/**
 * Access token the local relay and the local web app agree on. It protects
 * nothing: the local relay listens only on the loopback interface. Deployed
 * stages use a token generated by the relay Stack.
 */
export const LOCAL_REGISTRY_RELAY_ACCESS_TOKEN = Redacted.make("local-development-relay-token");

/** Environment variable that carries the relay access token to the relay process. */
export const REGISTRY_RELAY_ACCESS_TOKEN_VARIABLE = "ISAVAIL_RELAY_ACCESS_TOKEN";
